function normalizeSlackTickets(matches) {
  if (!Array.isArray(matches) || matches.length > 10)
    throw new Error("Slack search must return at most10 source messages.");
  const seen = new Set();
  return matches.map((m) => {
    const permalink = m.permalink,
      channel = m.channelName ?? m.channel?.name,
      username = m.username ?? "",
      userId = m.userId ?? m.user;
    if (
      typeof permalink !== "string" ||
      !/^https:\/\/[^/]+\/archives\/[^/]+\/p\d+$/.test(permalink) ||
      typeof m.text !== "string" ||
      typeof m.ts !== "string" ||
      typeof channel !== "string" ||
      typeof userId !== "string"
    )
      throw new Error("Slack message metadata is incomplete.");
    const id = "#" + permalink.split("/").pop();
    if (seen.has(id)) throw new Error("Duplicate Slack message hash.");
    seen.add(id);
    return {
      id,
      type: m.type ?? "message",
      channel,
      user: username + " (" + userId + ")",
      ts: m.ts,
      permalink,
      message: m.text,
    };
  });
}
function ticketHashes(issues) {
  const hashes = [];
  for (const issue of issues) {
    if (issue.description == null) continue;
    if (typeof issue.description !== "string") throw new Error("Linear description is not text.");
    const match = issue.description.match(/hash\:\s([\w#]+)/i);
    if (match && !hashes.includes(match[1])) hashes.push(match[1]);
  }
  return hashes;
}
function prepareSlackTickets({ matches }) {
  return { messages: normalizeSlackTickets(matches) };
}

