function supportTicketPrompt(message) {
  return (
    'The "user issue" is enclosed by 3 backticks:\n```\n' +
    message +
    '\n```\nYou will complete the following 4 tasks:\n1. Generate a title intended for a support ticket based on the user issue only. Be descriptive but use no more than 10 words.\n2. Summarise the user issue only by identifying the key expectations and steps that were taken to reach the conclusion.\n3. Offer at most 3 suggestions to debug or resolve the user issue only. ignore the previous issues for this task.\n4. Identify the urgency of the user issue only and denote the priority as one of "low", "medium", "high" or "urgent". If you cannot determine the urgency of the issue, then assign the "low" priority. Also consider that requests which require action either today or tomorrow should be prioritised as "high".'
  );
}
function validateSupportTicket(output) {
  if (
    !output ||
    typeof output !== "object" ||
    Array.isArray(output) ||
    Object.keys(output).some((k) => !["title", "summary", "ideas", "priority"].includes(k))
  )
    throw new Error("Invalid support ticket structure.");
  for (const k of ["title", "summary", "priority"])
    if (typeof output[k] !== "string" || !output[k].trim())
      throw new Error("Support ticket " + k + " is empty.");
  if (
    output.title.trim().split(/\s+/).length > 10 ||
    !Array.isArray(output.ideas) ||
    output.ideas.length > 3 ||
    output.ideas.some((i) => typeof i !== "string" || !i.trim()) ||
    !["low", "medium", "high", "urgent"].includes(output.priority)
  )
    throw new Error("Support ticket constraints were not satisfied.");
  return output;
}
function describeSupportTicket(message, output) {
  return (
    "## " +
    output.summary +
    "\n\n### Suggestions\n" +
    output.ideas.map((i) => "* " + i).join("\n") +
    "\n\n## Original Message\n" +
    message.user +
    " asks:\n> " +
    message.message +
    "\n\n### Metadata\nchannel: " +
    message.channel +
    "\nts: " +
    message.ts +
    "\npermalink: " +
    message.permalink +
    "\nhash: " +
    message.id +
    "\n"
  );
}

