return rows.map((item, index) => {
  const output = validateSupportTicket(item.json.output),
    message = messages[index].json.message;
  return {
    json: {
      title: output.title,
      description: describeSupportTicket(message, output),
      priority: { urgent: 1, high: 2, medium: 3, low: 4 }[output.priority],
      message,
    },
    pairedItem: { item: index },
  };
});

const rows = $input.all(),
  drafts = $("Validate Complete Ticket Draft Batch").all();
if (rows.length !== drafts.length) throw new Error("Created ticket count differs.");
const created = rows.map((item, index) => {
  if (typeof item.json.id !== "string" || !item.json.id)
    throw new Error("Missing created issue ID.");
  return {
    hash: drafts[index].json.message.id,
    id: item.json.id,
    identifier: item.json.identifier ?? null,
    url: item.json.url ?? null,
    title: drafts[index].json.title,
  };
});
return [{ json: { count: created.length, created }, pairedItem: { item: 0 } }];
